SELECT  primary_key, purchase_contract,purchase_contract_product,
name, model,un_modifiable_material_code, material_code, delivery_date, delivery,
contract_quantity, seller_send_quantity,received_quantity, qualified_quantity,
state, remark,data_version, business_belong,enterprise_code,unity_no,lack_procedure
FROM ${tableName} a
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'
AND purchase_contract = #{purchaseContract}

    AND ( name ILIKE '%'|| #{keyword} ||'%' OR model ILIKE '%'|| #{keyword} ||'%' )


    and (${dynamicTableNameProxy.getXiHangPartQuery("a.material_code","xihang",data.partUnityNo)}
        or ${dynamicTableNameProxy.getXiHangPartQuery("a.un_modifiable_material_code","xihang",data.partUnityNo)}
        or ( unity_no ILIKE '%'|| #{data.partUnityNo} ||'%' )
        )

ORDER BY id

