SELECT receivingDetail.purchase_contract_product as purchaseContractProduct, purchaseContract.contract_number AS purchaseContract, purchaseContract.vender_data_code AS supplierCode, purchaseContract.seller_name AS supplierName, receivingDetail.contract_quantity AS purchaseNum, receivingDetail.purchase_contract AS purchaseContractCode, GREATEST(receivingDetail.contract_quantity - receivingDetail.received_quantity, 0.0) AS onWayNum, GREATEST(receivingDetail.received_quantity, 0.0) AS receivedQuantity, TO_CHAR(purchaseContract.contract_time, 'YYYY-MM-DD') AS contractTime, receivingDetail.remark, (select pcs from ${productPartTName} where primary_key = receivingDetail.material_code) as pcs, COALESCE(receivingDetail.un_modifiable_material_code, receivingDetail.material_code) as productPartCode, purchaseContract.product_detail as productDetailJson FROM ${receivingDetailTName} as receivingDetail LEFT JOIN ${purchaseContractTName} as purchaseContract ON receivingDetail.purchase_contract = purchaseContract.primary_key WHERE receivingDetail.enterprise_code = #{enterpriseCode} AND ( receivingDetail.contract_quantity - receivingDetail.received_quantity > 0) AND receivingDetail.delete_flag = 'f' AND purchaseContract.state != 'CANCELED'
AND (receivingDetail.material_code = #{requestData.productPartCode} OR receivingDetail.un_modifiable_material_code = #{requestData.productPartCode})
